from pysat.solvers import Glucose3
from itertools import combinations, permutations
from collections import deque

n = 23

edge_to_var = {}
var_to_edge = {}
var_idx = 1
for i in range(n):
    for j in range(i+1, n):
        edge_to_var[(i,j)] = var_idx
        var_to_edge[var_idx] = (i,j)
        var_idx += 1

num_vars = var_idx - 1

def add_at_least_k(solver, vars_list, k):
    n_vars = len(vars_list)
    if k > n_vars:
        return False
    for combo in combinations(vars_list, n_vars - k + 1):
        solver.add_clause(list(combo))
    return True

def add_at_most_k(solver, vars_list, k):
    n_vars = len(vars_list)
    if k >= n_vars:
        return True
    for combo in combinations(vars_list, k + 1):
        solver.add_clause([-c for c in combo])
    return True

def check_girth(edge_list, n):
    adj = [[] for _ in range(n)]
    for u, v in edge_list:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

def find_5_cycles(edge_list, n):
    """Find all 5-cycles in the graph"""
    adj = [[] for _ in range(n)]
    for u, v in edge_list:
        adj[u].append(v)
        adj[v].append(u)

    cycles = set()
    for start in range(n):
        # BFS up to depth 3 to find 5-cycles
        # A 5-cycle through start: start-a-b-c-d-start
        # We need to find paths of length 4 from start back to start
        visited = {start: 0}
        queue = deque([(start, [start])])
        while queue:
            u, path = queue.popleft()
            if len(path) == 5:
                # Check if last vertex connects back to start
                if start in adj[u]:
                    cycle = tuple(sorted(path))
                    if cycle not in cycles:
                        cycles.add(cycle)
                continue
            for v in adj[u]:
                if v not in visited or visited[v] > len(path):
                    visited[v] = len(path)
                    queue.append((v, path + [v]))

    return cycles

solver = Glucose3()

# Triangle constraints
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add_clause([-edge_to_var[(i,j)], -edge_to_var[(i,k)], -edge_to_var[(j,k)]])

# 4-cycle constraints
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                solver.add_clause([-edge_to_var[(i,j)], -edge_to_var[(j,k)], -edge_to_var[(k,l)], -edge_to_var[(i,l)]])
                solver.add_clause([-edge_to_var[(i,j)], -edge_to_var[(j,l)], -edge_to_var[(k,l)], -edge_to_var[(i,k)]])
                solver.add_clause([-edge_to_var[(i,k)], -edge_to_var[(j,k)], -edge_to_var[(j,l)], -edge_to_var[(i,l)]])

# 5-cycle constraints - enumerate all possible 5-cycles
# A 5-cycle is determined by 5 vertices and a cyclic ordering
# For vertices i<j<k<l<m, we need to check all distinct 5-cycles
count_5 = 0
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                for m in range(l+1, n):
                    vertices = [i, j, k, l, m]
                    # Generate all distinct 5-cycles
                    # Fix i as first, then permute the rest
                    seen = set()
                    for perm in permutations([j, k, l, m]):
                        cycle = [i] + list(perm)
                        # Get edges
                        edges_in_cycle = []
                        for idx in range(5):
                            u, v = cycle[idx], cycle[(idx+1)%5]
                            if u > v:
                                u, v = v, u
                            edges_in_cycle.append((u, v))
                        edges_in_cycle.sort()
                        key = tuple(edges_in_cycle)
                        if key not in seen:
                            seen.add(key)
                            clause = [-edge_to_var[e] for e in edges_in_cycle]
                            solver.add_clause(clause)
                            count_5 += 1

print(f"Added {count_5} 5-cycle constraints")

# Degree constraints
for v in range(n):
    incident = []
    for u in range(v):
        incident.append(edge_to_var[(u,v)])
    for w in range(v+1, n):
        incident.append(edge_to_var[(v,w)])

    add_at_most_k(solver, incident, 4)
    add_at_least_k(solver, incident, 3)

print("Added degree constraints")

if solver.solve():
    model = solver.get_model()
    edge_list = []
    for var in range(1, num_vars + 1):
        if model[var-1] > 0:
            edge_list.append(var_to_edge[var])

    degrees = [0] * n
    for u, v in edge_list:
        degrees[u] += 1
        degrees[v] += 1

    girth = check_girth(edge_list, n)

    print(f"Edges: {len(edge_list)}")
    print(f"Degrees: {degrees}")
    print(f"Min degree: {min(degrees)}, Max degree: {max(degrees)}")
    print(f"Girth: {girth}")

    if min(degrees) >= 3 and max(degrees) <= 4 and girth >= 6:
        print("VALID SOLUTION!")
        print(edge_list)
    else:
        print("Solution doesn't meet all constraints")
else:
    print("UNSATISFIABLE")
